const knowledgeAnswers={
  '黑糖薑奶的熱飲標準配方是什麼？':{title:'700ml 熱飲標準配方：鮮奶 320ml、黑糖薑汁 35ml、熱水 80ml。',body:'依序將黑糖薑汁入杯，加入熱鮮奶，攪拌後確認中心溫度達 65°C。完成後核對熱飲杯標籤。',sources:['《飲品標準配方 v3.2》p.18','《熱飲製作 SOP》§ 2.4']},
  '燕麥奶不足時，跨店調撥的核准規則是什麼？':{title:'根據內部 SOP，建議先跨店調撥，且需店長核准。',body:'當單店庫存低於安全水位、且預估 6 小時內售罄時，系統可建立調撥草稿。若調撥量超過來源店安全庫存的 20%，須由區域主管再核准。',sources:['《跨店調撥 SOP》§ 3.2','《原料安全水位表》2026-10']},
  '上週哪一家分店的庫存差異最高？':{title:'學府店的庫存差異最高，整體差異率為 7.1%。',body:'主要差異來自燕麥奶與珍珠，合計占差異金額的 63%。建議先核對週四、週五晚間的報廢與員工飲用紀錄。',sources:['《五店庫存週報》10/06–10/12','《學府店盤點差異表》10/12']}
};
function renderKnowledgeAnswer(answer){const box=document.querySelector('#knowledgeAnswer');box.innerHTML=`<div class="answer-state"><span>AI</span><strong>${answer.title}</strong></div><p>${answer.body}</p><div class="source-list"><small>引用來源</small>${answer.sources.map(s=>`<button>${s}</button>`).join('')}</div>`;box.classList.remove('loading')}
function askKnowledge(){const input=document.querySelector('#knowledgeQuestion');const box=document.querySelector('#knowledgeAnswer');if(!input||!box)return;box.classList.add('loading');const answer=knowledgeAnswers[input.value.trim()]||{title:'目前知識庫沒有足夠資料回答。',body:'請補充相關 SOP、配方或報表後再查詢。POC 不會用模型常識猜測內部規則。',sources:['未找到可引用來源']};setTimeout(()=>renderKnowledgeAnswer(answer),550)}
document.querySelectorAll('[data-kb-question]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#knowledgeQuestion').value=button.dataset.kbQuestion;askKnowledge()}));
document.querySelector('#askKnowledge')?.addEventListener('click',askKnowledge);
document.querySelector('#knowledgeQuestion')?.addEventListener('keydown',event=>{if(event.key==='Enter')askKnowledge()});
document.querySelector('#runAgents')?.addEventListener('click',()=>{const button=document.querySelector('#runAgents');const a1=document.querySelector('#analystAgent');const a2=document.querySelector('#reportAgent');button.disabled=true;button.textContent='執行中…';a1.className='poc-agent running';a1.querySelector('b').textContent='分析中';a2.className='poc-agent';a2.querySelector('b').textContent='待命';setTimeout(()=>{a1.className='poc-agent done';a1.querySelector('b').textContent='完成';a2.className='poc-agent running';a2.querySelector('b').textContent='撰寫中'},900);setTimeout(()=>{a2.className='poc-agent done';a2.querySelector('b').textContent='完成';button.disabled=false;button.textContent='↻ 重新執行';document.querySelector('#reportStatus').textContent='剛剛產生・等待店長檢視';document.querySelector('#weeklyReport').scrollIntoView({behavior:'smooth',block:'start'});window.toast?.('兩個 Agent 已完成週報草稿')},1900)});
document.querySelector('#copyReport')?.addEventListener('click',async()=>{const text='五店營運週報：營收 NT$468,200（+8.2%）；學府店燕麥奶用量偏高；站前店熱飲占比增加；市場店耗損下降 NT$1,240；商辦店午餐團訂成長；社區店晚間多杯訂單穩定。';try{await navigator.clipboard.writeText(text);window.toast?.('週報摘要已複製')}catch{window.toast?.('瀏覽器未允許複製')}});
document.querySelector('#approveReport')?.addEventListener('click',()=>{document.querySelector('#reportStatus').textContent='已由林店長核准・PDF 匯出為正式版串接項目';window.toast?.('Demo 已記錄核准；正式版將產生 PDF')});
